import { defineConfig } from "wxt";
import tailwindcss from "@tailwindcss/vite";
import { PCM_WORKLET_SOURCE } from "@earshot/shared";

// See https://wxt.dev/api/config.html
export default defineConfig({
  modules: ["@wxt-dev/module-react"],
  vite: () => ({ plugins: [tailwindcss()] }),
  manifest: {
    name: "Earshot — Live AI Captions",
    short_name: "Earshot",
    description:
      "Real-time AI captions and a searchable transcript for any video or audio playing in a tab. Powered by Deepgram Nova-3.",
    minimum_chrome_version: "116",
    // Deliberately minimal: no host permissions and no always-on content scripts.
    permissions: ["tabCapture", "offscreen", "sidePanel", "storage", "activeTab", "scripting"],
    icons: { 16: "icon/16.png", 32: "icon/32.png", 48: "icon/48.png", 128: "icon/128.png" },
    action: {
      default_title: "Earshot — Live AI Captions",
      default_icon: { 16: "icon/16.png", 32: "icon/32.png" },
    },
  },
  hooks: {
    // Ship the AudioWorklet from the single source of truth in @earshot/shared.
    "build:publicAssets": (_wxt, files) => {
      files.push({ relativeDest: "pcm-worklet.js", contents: PCM_WORKLET_SOURCE });
    },
    "prepare:publicPaths": (_wxt, paths) => {
      paths.push("/pcm-worklet.js");
    },
  },
});
/**
 * The extension's whole message protocol, in one place.
 *
 * Contexts:
 * - background (service worker): orchestrates capture, owns no transcript state.
 * - offscreen document: runs the TranscriptionSession; SOURCE OF TRUTH for session state.
 * - popup / side panel: UI; read state with `get-state`, then follow broadcasts.
 * - overlay content script: caption box inside the captured tab.
 *
 * `runtime.sendMessage` reaches every extension page at once, so every runtime message
 * carries a `to` field and each context ignores messages that aren't addressed to it.
 */
import { browser } from "wxt/browser";
import type { CaptionState, TranscriptEvent, TranscriptionStatus, TranscriptState } from "@earshot/shared";

/** Everything the UI needs to render one capture session. Lives in the offscreen document. */
export interface SessionSnapshot {
  /** Tab being (or last) captured; null when nothing has been captured. */
  tabId: number | null;
  tabTitle: string | null;
  /** The user dismissed the in-page caption box for this capture. */
  overlayHidden: boolean;
  transcript: TranscriptState;
}

export type SessionMeta = Pick<SessionSnapshot, "tabId" | "tabTitle" | "overlayHidden">;

/** Generic reply for commands. */
export type CommandResult = { ok: true } | { ok: false; error: string };

/* ----------------------------- → background ----------------------------- */

export type BackgroundRequest =
  | { to: "background"; type: "start"; tabId: number }
  | { to: "background"; type: "stop" }
  | { to: "background"; type: "get-state" }
  /** Re-show (injecting if necessary) the caption box in the captured tab. */
  | { to: "background"; type: "show-overlay" }
  /** From the overlay: the user closed the caption box. */
  | { to: "background"; type: "overlay-dismissed" }
  /** From a freshly injected overlay: "what should I show?" (tab comes from sender). */
  | { to: "background"; type: "overlay-hello" };

export interface BackgroundResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "show-overlay": CommandResult;
  "overlay-dismissed": CommandResult;
  "overlay-hello": OverlayHello;
}

export interface OverlayHello {
  /** False when this tab is not the captured tab: the overlay should remove itself. */
  captured: boolean;
  hidden: boolean;
  status: TranscriptionStatus;
  caption: CaptionState | null;
}

/* ----------------------------- → offscreen ----------------------------- */

export type OffscreenRequest =
  | { to: "offscreen"; type: "start"; streamId: string; tabId: number; tabTitle: string | null; tokenEndpoint: string }
  | { to: "offscreen"; type: "stop" }
  | { to: "offscreen"; type: "get-state" }
  | { to: "offscreen"; type: "set-overlay-hidden"; hidden: boolean };

export interface OffscreenResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "set-overlay-hidden": CommandResult;
}

/* --------------------------- offscreen → everyone --------------------------- */

export type Broadcast =
  | { to: "broadcast"; type: "transcript-event"; tabId: number | null; event: TranscriptEvent }
  | { to: "broadcast"; type: "meta"; meta: SessionMeta };

/* ----------------------- background → overlay (tabs.sendMessage) ----------------------- */

export type OverlayMessage =
  | { to: "overlay"; type: "event"; event: TranscriptEvent }
  | { to: "overlay"; type: "show" }
  /** Capture ended for this tab: remove the overlay entirely. */
  | { to: "overlay"; type: "teardown" };

export type RuntimeMessage = BackgroundRequest | OffscreenRequest | Broadcast;

/* ----------------------------- typed helpers ----------------------------- */

export function sendToBackground<T extends BackgroundRequest>(msg: T): Promise<BackgroundResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

export function sendToOffscreen<T extends OffscreenRequest>(msg: T): Promise<OffscreenResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

/** Fire-and-forget broadcast; "no receiver" errors are expected when no UI is open. */
export function broadcast(msg: Broadcast): void {
  browser.runtime.sendMessage(msg).catch(() => undefined);
}

export function sendToOverlay(tabId: number, msg: OverlayMessage): Promise<unknown> {
  return browser.tabs.sendMessage(tabId, msg);
}

export function isRuntimeMessage(msg: unknown): msg is RuntimeMessage {
  return typeof msg === "object" && msg !== null && "to" in msg && "type" in msg;
}

export function isOverlayMessage(msg: unknown): msg is OverlayMessage {
  return typeof msg === "object" && msg !== null && (msg as { to?: unknown }).to === "overlay";
}

/** Statuses during which audio is being captured. */
export function isCapturing(status: TranscriptionStatus): boolean {
  return status === "connecting" || status === "live" || status === "paused" || status === "reconnecting";
}

export function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
import { browser } from "wxt/browser";
import { normalizeCaptionSettings, type CaptionSettings } from "@earshot/shared";

/** Build-time default (`WXT_EARSHOT_URL=https://earshot.example npx wxt build`). */
export const DEFAULT_EARSHOT_URL: string = (
  (import.meta.env.WXT_EARSHOT_URL as string | undefined) || "http://localhost:3100"
).replace(/\/+$/, "");

/** chrome.storage.local keys. Transcripts are never stored. */
export const STORAGE_KEYS = {
  serverUrl: "serverUrl",
  captionSettings: "captionSettings",
  overlayLayout: "overlayLayout",
} as const;

/** Caption box placement, as fractions of the viewport so it survives resizes / fullscreen. */
export interface OverlayLayout {
  /** Left edge, 0..1 of viewport width. */
  x: number;
  /** Top edge, 0..1 of viewport height. */
  y: number;
  /** Box width in CSS px. */
  width: number;
}

/** Normalize a user-entered server URL; returns null when it's not an http(s) origin. */
export function normalizeServerUrl(input: string): string | null {
  try {
    const url = new URL(input.trim());
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    return url.origin + url.pathname.replace(/\/+$/, "");
  } catch {
    return null;
  }
}

export async function getServerUrl(): Promise<string> {
  const stored = (await browser.storage.local.get(STORAGE_KEYS.serverUrl))[STORAGE_KEYS.serverUrl];
  return (typeof stored === "string" && normalizeServerUrl(stored)) || DEFAULT_EARSHOT_URL;
}

export function tokenEndpoint(serverUrl: string): string {
  return `${serverUrl}/api/deepgram/token`;
}

export async function getCaptionSettings(): Promise<CaptionSettings> {
  const stored = (await browser.storage.local.get(STORAGE_KEYS.captionSettings))[STORAGE_KEYS.captionSettings];
  return { ...normalizeCaptionSettings(stored), position: "overlay" };
}

/**
 * Pages Chrome never lets extensions capture or script. `url` is only known when we have
 * activeTab for the tab (popup) — undefined means "can't tell", so we let Chrome decide.
 */
export function restrictedReason(url: string | undefined): string | null {
  if (!url) return null;
  if (/^(chrome|edge|brave|about|devtools|view-source|chrome-extension|chrome-search|chrome-untrusted):/i.test(url)) {
    return "Chrome doesn't allow extensions to capture its own pages. Open a site with video or audio.";
  }
  if (/^https:\/\/(chromewebstore\.google\.com|chrome\.google\.com\/webstore)/i.test(url)) {
    return "Chrome doesn't allow extensions to run on the Chrome Web Store.";
  }
  return null;
}

/**
 * Background service worker: orchestrates a single capture at a time.
 *
 * It keeps NO session state of its own — MV3 may suspend it at any moment. Whenever it
 * needs to know what's going on it asks the offscreen document (`get-state`), which is
 * the source of truth. Transcript events carry their tabId, so relaying them to the
 * captured tab's overlay needs no memory either.
 */
import { browser, type Browser } from "wxt/browser";
import { defineBackground } from "wxt/utils/define-background";
import { initialTranscriptState, type TranscriptEvent } from "@earshot/shared";
import { getServerUrl, restrictedReason, tokenEndpoint } from "@/utils/config";
import {
  errorMessage,
  isCapturing,
  isRuntimeMessage,
  sendToOffscreen,
  sendToOverlay,
  type BackgroundRequest,
  type BackgroundResponses,
  type CommandResult,
  type OverlayHello,
  type SessionSnapshot,
} from "@/utils/messages";

const OFFSCREEN_PATH = "/offscreen.html";
const OVERLAY_SCRIPT = "/content-scripts/overlay.js";
const LIVE_COLOR = "#e5484d";

export default defineBackground(() => {
  /* ------------------------------ offscreen ------------------------------ */

  let creatingOffscreen: Promise<void> | null = null;

  async function hasOffscreen(): Promise<boolean> {
    const contexts = await browser.runtime.getContexts({
      contextTypes: ["OFFSCREEN_DOCUMENT" as Browser.runtime.ContextType],
      documentUrls: [browser.runtime.getURL(OFFSCREEN_PATH)],
    });
    return contexts.length > 0;
  }

  async function ensureOffscreen(): Promise<void> {
    if (await hasOffscreen()) return;
    creatingOffscreen ??= browser.offscreen
      .createDocument({
        url: OFFSCREEN_PATH,
        reasons: ["USER_MEDIA" as Browser.offscreen.Reason],
        justification: "Capture the audio of the tab the user chose and stream it to Deepgram for live captions.",
      })
      .finally(() => {
        creatingOffscreen = null;
      });
    await creatingOffscreen;
  }

  async function closeOffscreen(): Promise<void> {
    if (await hasOffscreen()) await browser.offscreen.closeDocument().catch(() => undefined);
  }

  /** Re-learn the session from the offscreen document (survives service worker restarts). */
  async function getSnapshot(): Promise<SessionSnapshot> {
    if (creatingOffscreen) await creatingOffscreen.catch(() => undefined);
    if (await hasOffscreen()) {
      try {
        const snap = await sendToOffscreen({ to: "offscreen", type: "get-state" });
        if (snap) return snap;
      } catch {
        /* document is closing */
      }
    }
    return { tabId: null, tabTitle: null, overlayHidden: false, transcript: initialTranscriptState() };
  }

  /* ------------------------------ indicators ------------------------------ */

  async function setLiveBadge(tabId: number, live: boolean) {
    try {
      await browser.action.setBadgeText({ tabId, text: live ? "LIVE" : "" });
      if (live) {
        await browser.action.setBadgeBackgroundColor({ tabId, color: LIVE_COLOR });
        await browser.action.setBadgeTextColor?.({ tabId, color: "#ffffff" });
      }
      await browser.action.setTitle({
        tabId,
        title: live ? "Earshot — capturing this tab's audio (click to stop)" : "Earshot — Live AI Captions",
      });
    } catch {
      /* tab is gone */
    }
  }

  async function injectOverlay(tabId: number): Promise<boolean> {
    try {
      await browser.scripting.executeScript({ target: { tabId }, files: [OVERLAY_SCRIPT] });
      return true;
    } catch {
      // chrome:// pages, the Web Store, PDFs, or activeTab no longer granted after navigation.
      return false;
    }
  }

  /* ------------------------------ commands ------------------------------ */

  function explainCaptureError(err: unknown): string {
    const msg = errorMessage(err);
    if (/invoked|activeTab/i.test(msg)) {
      return "Chrome only allows capture after you use Earshot on this tab. Click the Earshot toolbar icon on this tab, then Start.";
    }
    if (/active stream/i.test(msg)) {
      return "This tab's audio is already being captured (by Earshot or another extension). Stop that capture and try again.";
    }
    if (/chrome pages|cannot be captured/i.test(msg)) {
      return "Chrome doesn't allow capturing this page.";
    }
    return `Could not capture this tab: ${msg}`;
  }

  async function start(tabId: number): Promise<CommandResult> {
    const tab = await browser.tabs.get(tabId).catch(() => null);
    if (!tab) return { ok: false, error: "That tab no longer exists." };
    const restricted = restrictedReason(tab.url);
    if (restricted) return { ok: false, error: restricted };

    // One capture at a time: stop whatever is running (on this or another tab) first.
    const current = await getSnapshot();
    if (current.tabId !== null && isCapturing(current.transcript.status)) await stop();

    let streamId: string;
    try {
      streamId = await browser.tabCapture.getMediaStreamId({ targetTabId: tabId });
    } catch (err) {
      return { ok: false, error: explainCaptureError(err) };
    }

    try {
      await ensureOffscreen();
      const res = await sendToOffscreen({
        to: "offscreen",
        type: "start",
        streamId,
        tabId,
        tabTitle: tab.title ?? null,
        tokenEndpoint: tokenEndpoint(await getServerUrl()),
      });
      if (!res?.ok) {
        await closeOffscreen();
        return res ?? { ok: false, error: "The audio capture page did not respond." };
      }
    } catch (err) {
      await closeOffscreen();
      return { ok: false, error: `Could not start audio capture: ${errorMessage(err)}` };
    }

    await setLiveBadge(tabId, true);
    void injectOverlay(tabId);
    return { ok: true };
  }

  async function stop(): Promise<CommandResult> {
    const snap = await getSnapshot();
    if (await hasOffscreen()) {
      // session.stop() flushes final words and closes socket + audio before replying.
      await sendToOffscreen({ to: "offscreen", type: "stop" }).catch(() => undefined);
      await closeOffscreen();
    }
    if (snap.tabId !== null) {
      await setLiveBadge(snap.tabId, false);
      sendToOverlay(snap.tabId, { to: "overlay", type: "teardown" }).catch(() => undefined);
    }
    return { ok: true };
  }

  async function showOverlay(): Promise<CommandResult> {
    const snap = await getSnapshot();
    if (snap.tabId === null || !isCapturing(snap.transcript.status)) {
      return { ok: false, error: "Captions aren't running." };
    }
    await sendToOffscreen({ to: "offscreen", type: "set-overlay-hidden", hidden: false });
    try {
      await sendToOverlay(snap.tabId, { to: "overlay", type: "show" });
      return { ok: true };
    } catch {
      return (await injectOverlay(snap.tabId))
        ? { ok: true }
        : { ok: false, error: "Chrome didn't allow showing captions on this page. Use the transcript panel instead." };
    }
  }

  async function overlayHello(tabId: number | undefined): Promise<OverlayHello> {
    const snap = await getSnapshot();
    const captured = tabId !== undefined && snap.tabId === tabId && isCapturing(snap.transcript.status);
    return {
      captured,
      hidden: snap.overlayHidden,
      status: snap.transcript.status,
      caption: captured ? snap.transcript.caption : null,
    };
  }

  /* ------------------------------ relaying ------------------------------ */

  function relay(tabId: number | null, event: TranscriptEvent) {
    if (tabId === null) return;
