input.content:
// Earshot extension BYOK smoke test (test-only). Usage: EARSHOT_TEST_DG_KEY=... node smoke-byok.mjs headful
// Requires NO Earshot server on SERVER_URL. Never prints the key.
import { createRequire } from "node:module";
import { createReadStream, mkdirSync, rmSync, statSync } from "node:fs";
import http from "node:http";
import { join } from "node:path";

const REPO = "/Users/rizelscarlett/Documents/agent-experiments/voice-experiments/live-captions";
const SCRATCH = new URL(".", import.meta.url).pathname;
const EXT = join(REPO, "apps/extension/.output/chrome-mv3");
const WAV = join(SCRATCH, "media/spacewalk.wav");
const PORT = 4510;
const KEY = process.env.EARSHOT_TEST_DG_KEY;
if (!KEY) throw new Error("EARSHOT_TEST_DG_KEY not set");
const BAD_KEY = "0123456789abcdef0123456789abcdef01234567";
const headless = process.argv[2] !== "headful";
const puppeteer = createRequire(join(REPO, "package.json"))("puppeteer-core");
const shots = join(SCRATCH, "shots-byok");
mkdirSync(shots, { recursive: true });
const profile = join(SCRATCH, `profile-byok-${Date.now()}`);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log("[byok]", ...a);
const redact = (s) => (typeof s === "string" ? s.split(KEY).join("[KEY]").replace(/••••\S{4}/g, "••••[last4]") : s);
const results = {};
const check = (name, ok, detail) => {
  results[name] = { ok: Boolean(ok), ...(detail !== undefined ? { detail: redact(detail) } : {}) };
  log(ok ? "PASS" : "FAIL", name, detail !== undefined ? redact(JSON.stringify(detail)) : "");
};

const server = http
  .createServer((req, res) => {
    if (req.url?.startsWith("/spacewalk.wav")) {
      res.writeHead(200, { "Content-Type": "audio/wav", "Content-Length": statSync(WAV).size });
      createReadStream(WAV).pipe(res);
      return;
    }
    res.writeHead(200, { "Content-Type": "text/html" });
    res.end(`<!doctype html><title>Earshot smoke page</title><body style="background:#222;color:#eee">
      <h1>Smoke test media page</h1><audio id="a" src="/spacewalk.wav" controls loop></audio></body>`);
  })
  .listen(PORT);

const browser = await puppeteer.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  headless,
  pipe: true,
  enableExtensions: true,
  userDataDir: profile,
  args: ["--autoplay-policy=no-user-gesture-required", "--no-first-run", "--no-default-browser-check", "--window-size=1280,860"],
  defaultViewport: null,
});

const consoleMsgs = [];
const watch = (page, label) => {
  page.on("console", (m) => consoleMsgs.push(`${label} ${m.type()}: ${m.text()}`));
  page.on("pageerror", (e) => consoleMsgs.push(`${label} pageerror: ${e.message}`));
};
const text = (p, sel = "body") => p.evaluate((s) => document.querySelector(s)?.innerText.replace(/\s+/g, " ") ?? null, sel);
const clickByText = (p, re) =>
  p.evaluate((src) => {
    const r = new RegExp(src);
    const b = [...document.querySelectorAll("button")].find((x) => r.test(x.textContent));
    b?.click();
    return Boolean(b);
  }, re.source);
const waitFor = async (fn, ms = 15000) => {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    const v = await fn().catch(() => null);
    if (v) return v;
    await sleep(250);
  }
  return null;
};

try {
  const id = await browser.installExtension(EXT);
  const ext = (await browser.extensions()).get(id);
  log("installed", id);

  // ---------- 1. first run: no key, no server → needs-key notice in popup + panel ----------
  const panel = await browser.newPage();
  watch(panel, "sidepanel");
  await panel.setViewport({ width: 400, height: 800 });
  await panel.goto(`chrome-extension://${id}/sidepanel.html`, { waitUntil: "load" });
  const panelNeeds = await waitFor(() => text(panel, '[data-testid="needs-key"]'), 8000);
  check("panelNeedsKeyNoServer", /Add a Deepgram API key/.test(panelNeeds ?? ""), panelNeeds);
  await panel.screenshot({ path: join(shots, "panel-needs-key.png") });

  const media = await browser.newPage();
  watch(media, "media");
  await media.goto(`http://localhost:${PORT}/`, { waitUntil: "load" });
  await media.evaluate(() => document.getElementById("a").play());
  await media.bringToFront();
  await sleep(500);

  // Real popup via the toolbar action; "Add your key" must open the side panel on the key setting.
  await media.triggerExtensionAction(ext);
  let popup = await (await browser.waitForTarget((t) => t.url().endsWith("/popup.html"), { timeout: 5000 })).asPage();
  watch(popup, "popup");
  const popupNeeds = await waitFor(() => text(popup, '[data-testid="needs-key"]'), 8000);
  check("popupNeedsKeyNoServer", /Add a Deepgram API key/.test(popupNeeds ?? ""), popupNeeds);
  check("popupHidesWebLinkWithoutServer", !/Open Earshot web/.test((await text(popup)) ?? ""));
  await popup.screenshot({ path: join(shots, "popup-needs-key.png") }).catch(() => undefined);

  // Starting anyway explains the problem up front (no capture attempted).
  await popup.click('button[role="switch"]');
  const popupErr = await waitFor(() => text(popup, '[role="alert"]'), 8000);
  check("startWithoutKeyExplains", /needs a Deepgram API key/.test(popupErr ?? "") && /Add your Deepgram key/.test(popupErr ?? ""), popupErr);
  const badgeNoKey = await (await ext.workers())[0].evaluate(async () => (await chrome.tabs.query({ active: true, lastFocusedWindow: true }))[0]?.id).then(
    async (t) => (await ext.workers())[0].evaluate((tt) => chrome.action.getBadgeText({ tabId: tt }), t),
  );
  check("noBadgeWhenRefused", badgeNoKey === "", badgeNoKey);

  const clickedAdd = await clickByText(popup, /Add your key/);
  const realPanelTarget = await browser
    .waitForTarget((t) => t.url().endsWith("/sidepanel.html") && t !== panel.target(), { timeout: 5000 })
    .catch(() => null);
  let realPanelView = null;
  if (realPanelTarget) {
    const rp = await realPanelTarget.asPage();
    realPanelView = await waitFor(
      () => rp.evaluate(() => (document.querySelector("#deepgram-key") ? { focused: document.activeElement?.id === "deepgram-key" } : null)),
      5000,
    );
  }
  check("popupAddKeyOpensPanelSettings", clickedAdd && realPanelView, { clickedAdd, realPanelOpened: Boolean(realPanelTarget), realPanelView });
  await popup.close().catch(() => undefined);

  // ---------- 2. side panel settings: bad key rejected ----------
  await panel.bringToFront();
  await clickByText(panel, /^Settings$/);
  await panel.waitForSelector("#deepgram-key");
  check("statusBeforeKey", /no Earshot server is reachable/.test((await text(panel, '[data-testid="key-status"]')) ?? ""), await text(panel, '[data-testid="key-status"]'));
  await panel.type("#deepgram-key", BAD_KEY);
  await clickByText(panel, /Verify & save/);
  const badMsg = await waitFor(() => panel.evaluate(() => document.querySelector('[data-testid="key-message"]')?.textContent), 12000);
  const storedAfterBad = await panel.evaluate(async () => Boolean((await chrome.storage.local.get("deepgramKey")).deepgramKey));
  check("badKeyRejected", /Deepgram rejected this key/.test(badMsg ?? "") && !storedAfterBad, { badMsg, storedAfterBad });
  await panel.screenshot({ path: join(shots, "panel-bad-key.png") });

  // Garbage that isn't key-shaped is caught before any network call.
  await panel.evaluate(() => {
    const i = document.querySelector("#deepgram-key");
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set.call(i, "");
    i.dispatchEvent(new Event("input", { bubbles: true }));
  });
  await panel.type("#deepgram-key", "not a key");
  await clickByText(panel, /Verify & save/);
  const shapeMsg = await waitFor(() => panel.evaluate(() => document.querySelector('[data-testid="key-message"]')?.textContent), 3000);
