// Earshot extension BYOK smoke test (test-only). Usage: EARSHOT_TEST_DG_KEY=... node smoke-byok.mjs headful
// Requires NO Earshot server on SERVER_URL. Never prints the key.
import { createRequire } from "node:module";
import { createReadStream, mkdirSync, rmSync, statSync } from "node:fs";
import http from "node:http";
import { join } from "node:path";

const REPO = "/Users/rizelscarlett/Documents/agent-experiments/voice-experiments/live-captions";
const SCRATCH = new URL(".", import.meta.url).pathname;
const EXT = join(REPO, "apps/extension/.output/chrome-mv3");
const WAV = join(SCRATCH, "media/spacewalk.wav");
const PORT = 4510;
const KEY = process.env.EARSHOT_TEST_DG_KEY;
if (!KEY) throw new Error("EARSHOT_TEST_DG_KEY not set");
const BAD_KEY = "0123456789abcdef0123456789abcdef01234567";
const headless = process.argv[2] !== "headful";
const puppeteer = createRequire(join(REPO, "package.json"))("puppeteer-core");
const shots = join(SCRATCH, "shots-byok");
mkdirSync(shots, { recursive: true });
const profile = join(SCRATCH, `profile-byok-${Date.now()}`);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log("[byok]", ...a);
const redact = (s) => (typeof s === "string" ? s.split(KEY).join("[KEY]").replace(/••••\S{4}/g, "••••[last4]") : s);
const results = {};
const check = (name, ok, detail) => {
  results[name] = { ok: Boolean(ok), ...(detail !== undefined ? { detail: redact(detail) } : {}) };
  log(ok ? "PASS" : "FAIL", name, detail !== undefined ? redact(JSON.stringify(detail)) : "");
};

const server = http
  .createServer((req, res) => {
    if (req.url?.startsWith("/spacewalk.wav")) {
      res.writeHead(200, { "Content-Type": "audio/wav", "Content-Length": statSync(WAV).size });
      createReadStream(WAV).pipe(res);
      return;
    }
    res.writeHead(200, { "Content-Type": "text/html" });
    res.end(`<!doctype html><title>Earshot smoke page</title><body style="background:#222;color:#eee">
      <h1>Smoke test media page</h1><audio id="a" src="/spacewalk.wav" controls loop></audio></body>`);
  })
  .listen(PORT);

const browser = await puppeteer.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  headless,
  pipe: true,
  enableExtensions: true,
  userDataDir: profile,
  args: ["--autoplay-policy=no-user-gesture-required", "--no-first-run", "--no-default-browser-check", "--window-size=1280,860"],
  defaultViewport: null,
});

const consoleMsgs = [];
const watch = (page, label) => {
  page.on("console", (m) => consoleMsgs.push(`${label} ${m.type()}: ${m.text()}`));
  page.on("pageerror", (e) => consoleMsgs.push(`${label} pageerror: ${e.message}`));
};
const text = (p, sel = "body") => p.evaluate((s) => document.querySelector(s)?.innerText.replace(/\s+/g, " ") ?? null, sel);
const clickByText = (p, re) =>
  p.evaluate((src) => {
    const r = new RegExp(src);
    const b = [...document.querySelectorAll("button")].find((x) => r.test(x.textContent));
    b?.click();
    return Boolean(b);
  }, re.source);
const waitFor = async (fn, ms = 15000) => {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    const v = await fn().catch(() => null);
    if (v) return v;
    await sleep(250);
  }
  return null;
};

