  );
  const keyStatus = await waitFor(() => panel.evaluate(() => { const t = document.querySelector('[data-testid="key-status"]')?.textContent; return /Using your key/.test(t) ? t : null; }), 3000);
  const stored = await panel.evaluate(async (k) => (await chrome.storage.local.get("deepgramKey")).deepgramKey === k, KEY);
